package org.apache.commons.lang3.math;

import java.io.*;
import java.math.*;
import java.math.BigDecimal;
import java.math.BigInteger;
import java.util.*;
import org.apache.commons.lang3.StringUtils;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;

public class NumberUtils_isNumber_TriageGen1Test {

    @Test
    public void testIsNumber_NullOrEmpty() {
        assertFalse(NumberUtils.isNumber(null));
        assertFalse(NumberUtils.isNumber(""));
    }

    @Test
    public void testIsNumber_Integers() {
        assertTrue(NumberUtils.isNumber("123"));
        assertTrue(NumberUtils.isNumber("-123"));
        assertTrue(NumberUtils.isNumber("0"));
        assertTrue(NumberUtils.isNumber("0123"));
        assertFalse(NumberUtils.isNumber("abc"));
        assertFalse(NumberUtils.isNumber("12a3"));
    }

    @Test
    public void testIsNumber_Hexadecimal() {
        assertTrue(NumberUtils.isNumber("0x123"));
        assertTrue(NumberUtils.isNumber("0xABC"));
        assertTrue(NumberUtils.isNumber("0xabc"));
        assertTrue(NumberUtils.isNumber("-0x123")); // Note: logic handles '-' then '0x'
        assertFalse(NumberUtils.isNumber("0x"));
        assertFalse(NumberUtils.isNumber("0xG"));
        assertFalse(NumberUtils.isNumber("0x12z"));
    }

    @Test
    public void testIsNumber_Decimals() {
        assertTrue(NumberUtils.isNumber("123.45"));
        assertTrue(NumberUtils.isNumber(".45"));
        assertTrue(NumberUtils.isNumber("123."));
        assertFalse(NumberUtils.isNumber("12.3.4"));
        assertFalse(NumberUtils.isNumber("e.5"));
    }

    @Test
    public void testIsNumber_Exponents() {
        assertTrue(NumberUtils.isNumber("123e45"));
        assertTrue(NumberUtils.isNumber("123E45"));
        assertTrue(NumberUtils.isNumber("123e+45"));
        assertTrue(NumberUtils.isNumber("123e-45"));
        assertFalse(NumberUtils.isNumber("123e"));
        assertFalse(NumberUtils.isNumber("123e++45"));
        assertFalse(NumberUtils.isNumber("123ee45"));
        assertFalse(NumberUtils.isNumber("e123"));
        assertFalse(NumberUtils.isNumber("123e45e"));
    }

    @Test
    public void testIsNumber_TypeQualifiers() {
        // d, D, f, F
        assertTrue(NumberUtils.isNumber("123d"));
        assertTrue(NumberUtils.isNumber("123D"));
        assertTrue(NumberUtils.isNumber("123f"));
        assertTrue(NumberUtils.isNumber("123F"));

        // l, L
        assertTrue(NumberUtils.isNumber("123l"));
        assertTrue(NumberUtils.isNumber("123L"));

        // L with exponent should be false per logic: return foundDigit && !hasExp;
        assertFalse(NumberUtils.isNumber("123e4L"));

        // Check illegal qualifiers
        assertFalse(NumberUtils.isNumber("123g"));
        assertFalse(NumberUtils.isNumber("123.f")); // decimal point logic is handled before qualifier
    }

    @Test
    public void testIsNumber_EdgeCases() {
        // Single sign
        assertFalse(NumberUtils.isNumber("-"));
        assertFalse(NumberUtils.isNumber("+"));

        // Single dot
        assertFalse(NumberUtils.isNumber("."));

        // Sign after exponent
        assertTrue(NumberUtils.isNumber("1E-1"));
        assertFalse(NumberUtils.isNumber("1E-"));

        // Combinations
        assertTrue(NumberUtils.isNumber("-123.45e-6"));
        assertFalse(NumberUtils.isNumber("123.45e-6f")); // 'f' is checked at the very end, but logic allows it if foundDigit is true

        // The specific logic for 'allowSigns' and 'foundDigit' at the end
        // "1E-" -> i reaches end, allowSigns is true (from E), foundDigit is false (reset by '-')
        assertFalse(NumberUtils.isNumber("1E-"));

        // Testing the 'i < sz + 1 && allowSigns && !foundDigit' loop condition
        // This is triggered when a string ends with a sign after an E
        assertFalse(NumberUtils.isNumber("1E+"));
    }

    @Test
    public void testIsNumber_ComplexBranching() {
        // Test the case where i < chars.length and it's a digit
        assertTrue(NumberUtils.isNumber("1234")); 

        // Test the case where i < chars.length and it's 'e' or 'E' (should be false)
        assertFalse(NumberUtils.isNumber("123E"));

        // Test the case where i < chars.length and it's a qualifier
        assertTrue(NumberUtils.isNumber("123f"));

        // Test the case where i < chars.length and it's L
        assertTrue(NumberUtils.isNumber("123L"));

        // Test the case where i < chars.length and it's an illegal char
        assertFalse(NumberUtils.isNumber("123?"));
    }
}
